function validate([ip, n]) {
  if (typeof ip !== 'string' || ip.length < 7 || ip.length > 15) return 'ip has 7 to 15 characters.';
  const parts = ip.split('.');
  if (parts.length !== 4 || !parts.every(part => /^(0|[1-9][0-9]{0,2})$/.test(part) && Number(part) <= 255)) return 'ip must look like "a.b.c.d" with numbers from 0 to 255 and no leading zeros.';
  if (!Number.isInteger(n) || n < 1 || n > 1000) return 'n is between 1 and 1000.';
  const start = parts.reduce((value, part) => value * 256 + Number(part), 0);
  if (start + n - 1 > 4294967295) return 'The range must end at or before 255.255.255.255.';
  return null;
}

