function ipToCIDR(ip, n) {
  let start = 0;
  for (const part of ip.split('.')) {
    start = start * 256 + Number(part);
  }
  const blocks = [];
  while (n > 0) {
    let size = 1;
    let prefix = 32;
    while (size * 2 <= n && (start & size) === 0) {
      size *= 2;
      prefix--;
    }
    const address = [24, 16, 8, 0].map(shift => (start >>> shift) & 255).join('.');
    blocks.push(address + '/' + prefix);
    start += size;
    n -= size;
  }
  return blocks;
}

