function ipToCIDR(ip, n) {
  // Split the whole address space like a binary tree and keep every largest node that lies inside the range.
  const [a, b, c, d] = ip.split('.').map(Number);
  const first = ((a * 256 + b) * 256 + c) * 256 + d;
  const last = first + n - 1;
  const format = value => [Math.floor(value / 16777216) % 256, Math.floor(value / 65536) % 256, Math.floor(value / 256) % 256, value % 256].join('.');
  const blocks = [];
  const visit = (low, size, prefix) => {
    const high = low + size - 1;
    if (high < first || low > last) return;
    if (low >= first && high <= last) {
      blocks.push(format(low) + '/' + prefix);
      return;
    }
    visit(low, size / 2, prefix + 1);
    visit(low + size / 2, size / 2, prefix + 1);
  };
  visit(0, 2 ** 32, 0);
  return blocks;
}

