function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const top = 2 ** 32;
  const n = size === 'large' ? 900 + pick(101) : 1 + pick(40);
  const mode = pick(4);
  let start;
  if (mode === 0) start = pick(top - n + 1);
  else if (mode === 1) {
    // Just before (or at) an aligned boundary, so blocks of many sizes appear.
    const boundary = 2 ** (4 + pick(28));
    start = boundary * (1 + pick(top / boundary - 1)) - pick(n + 1);
  } else if (mode === 2) start = top - n - pick(3);
  else start = pick(20);
  start = Math.max(0, Math.min(start, top - n));
  const ip = [Math.floor(start / 16777216) % 256, Math.floor(start / 65536) % 256, Math.floor(start / 256) % 256, start % 256].join('.');
  return [ip, n];
}
